-- Messages of a conversation.
-- IDs are UUIDs generated by the application (Hibernate), and so is created_at, like every other timestamp in the
-- schema.
--
-- Delete behavior: neither a conversation nor a user with messages can be deleted (restrict). Nothing in the
-- application deletes either: deleted groups keep their row (V3) and there is no account deletion. Whoever adds
-- a purge of deleted groups or account deletion has to decide what happens to the messages, instead of the
-- database silently removing them.

create table messages (
    id              uuid          primary key,
    conversation_id uuid          not null references conversations (id) on delete restrict,
    sender_id       uuid          not null references users (id) on delete restrict,
    -- Stored as sent. The application allows at most 4000 UTF-16 code units, which is never more than 4000
    -- characters, the limit of this column.
    content         varchar(4000) not null,
    created_at      timestamptz   not null,
    -- The application rejects content without any non-whitespace character. ASCII whitespace is a subset of what
    -- it counts as whitespace, so this check never rejects content the application accepted.
    constraint messages_content_not_blank check (btrim(content, E' \t\n\r\f\x0B') <> '')
);

-- A conversation's history, newest first: "where conversation_id = ? order by created_at desc, id desc", and the
-- same from a cursor with "(created_at, id) < (?, ?)". PostgreSQL reads the index backwards, so it needs no sort,
-- and stops after one page. Also serves the count of a conversation's messages.
create index messages_conversation_id_created_at_id_idx on messages (conversation_id, created_at, id);
